import { ASSET_BASE } from '@/phaser-game/assets';

/**
 * Art contract for ZHULONG.
 *
 * Tiles and characters come from Frogatto & Friends (CC-BY-NC-SA 4.0), copied
 * into `public/vendor/frogatto` and catalogued in ATTRIBUTION.md. Light falloff
 * maps are generated by `scripts/zhulong/make-light.mjs`. This module is the
 * only place that knows file names; the scene only knows semantic keys.
 */

const ROOT = `${ASSET_BASE}/vendor/frogatto`;

/** Frogatto tilesheets: 8 cells per row, 32px each. */
export const SHEET_KEYS = ['dungeon-walls', 'dungeon-floor-cement', 'cave', 'dungeon-pillars', 'dungeon-parallax-wall', 'dungeon-parallax-floor'] as const;
/** Animated creature strips; frame width is per-strip and lives in the scene. */
export const SPRITE_KEYS = ['nene-spritesheet1', 'beetle-black-armor', 'moth-black', 'jellybug-green', 'maggot-grey', 'bat-black'] as const;

export const sheetUrl = (name: string): string => `${ROOT}/${name}.png`;
export const lightUrl = (name: string): string => `${ROOT}/light/${name}.png`;

export const LIGHT_KEYS = ['circle_a', 'circle_b', 'circle_a_noise', 'circle_a_streaks'] as const;

/** Palette. Warmth only exists where fire or ore exists; stone goes cold. */
export const C = {
  void: 0x0a0d16,
  ink: 0x0b0913,
  panel: 0x120e1c,
  line: 0x2c2540,
  stone: 0x8b8aa3,
  paper: 0xe8e3f0,
  dim: 0x7c7893,
  ember: 0xff7a2f,
  emberHot: 0xffc46b,
  emberDeep: 0xd2412a,
  jade: 0x49a8b0,
  jadeLight: 0x9fe3dd,
  gold: 0xf7c948,
  blood: 0x9c3540,
  bloodLight: 0xd15c52,
  tide: 0xb02a3c,
} as const;

export const hex = (n: number): string => `#${n.toString(16).padStart(6, '0')}`;

export { hash2 } from './sim/math';
